with feeders as (
    select
        md5(upper('HUB_DOCUMENT|' || (HUB_DOCUMENT_BK__INWARD_ID))) as HUB_DOCUMENT_HK
        , POD_NO as PROOF_OF_DELIVERY_NUMBER
        , DOC_REMARK as DOCUMENT_REMARKS
        , DOC_REC_TIME as RECEIVED_TIME
        , cast(null as varchar) as ATTACHMENT_SEQUENCE_NUMBER
        , cast(null as varchar) as RELATED_PRE_AUTHORISATION_REFERENCE
        , cast(null as varchar) as ORIGINATING_FAX_NUMBER
        , 'BJAZ_HM_INWARD_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_inward_dtls') }}
    where (nullif(trim(INWARD_ID),'')) is not null
    union all
    select
        md5(upper('HUB_DOCUMENT|' || (HUB_DOCUMENT_BK__OMNI_INWARD_NO_REPORT_ATTACH_PATH))) as HUB_DOCUMENT_HK
        , cast(null as varchar) as PROOF_OF_DELIVERY_NUMBER
        , cast(null as varchar) as DOCUMENT_REMARKS
        , cast(null as varchar) as RECEIVED_TIME
        , ATTACHMENT_ID as ATTACHMENT_SEQUENCE_NUMBER
        , HOS_REF_ID as RELATED_PRE_AUTHORISATION_REFERENCE
        , cast(null as varchar) as ORIGINATING_FAX_NUMBER
        , 'BJAZ_HM_PREAUTH_ATTACH' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_preauth_attach') }}
    where (coalesce(nullif('OMNI_INWARD:' || nullif(trim(OMNI_INWARD_NO),''), 'OMNI_INWARD:'), md5(normalise(upper(nullif(trim(REPORT_ATTACH_PATH),'')))))) is not null
    union all
    select
        md5(upper('HUB_DOCUMENT|' || (HUB_DOCUMENT_BK__INWARDNO))) as HUB_DOCUMENT_HK
        , cast(null as varchar) as PROOF_OF_DELIVERY_NUMBER
        , cast(null as varchar) as DOCUMENT_REMARKS
        , cast(null as varchar) as RECEIVED_TIME
        , cast(null as varchar) as ATTACHMENT_SEQUENCE_NUMBER
        , cast(null as varchar) as RELATED_PRE_AUTHORISATION_REFERENCE
        , FAX_NO as ORIGINATING_FAX_NUMBER
        , 'NG_FAX_INWARD_DETAILS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ng_fax_inward_details') }}
    where (nullif('INWARD:' || nullif(trim(INWARDNO),''), 'INWARD:')) is not null
),

resolved as (
    select
        HUB_DOCUMENT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PROOF_OF_DELIVERY_NUMBER end) as PROOF_OF_DELIVERY_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DOCUMENT_REMARKS end) as DOCUMENT_REMARKS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RECEIVED_TIME end) as RECEIVED_TIME,
        max(case when SOURCE_RUN = 'opus_health_v2' then ATTACHMENT_SEQUENCE_NUMBER end) as ATTACHMENT_SEQUENCE_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_v2' then RELATED_PRE_AUTHORISATION_REFERENCE end) as RELATED_PRE_AUTHORISATION_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then ORIGINATING_FAX_NUMBER end) as ORIGINATING_FAX_NUMBER,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_DOCUMENT_HK
),

hashed as (
    select
        *,
        case when PROOF_OF_DELIVERY_NUMBER is not null or DOCUMENT_REMARKS is not null or RECEIVED_TIME is not null or ATTACHMENT_SEQUENCE_NUMBER is not null or RELATED_PRE_AUTHORISATION_REFERENCE is not null or ORIGINATING_FAX_NUMBER is not null
                     then md5(upper(coalesce(cast(PROOF_OF_DELIVERY_NUMBER as varchar), '') || '|' || coalesce(cast(DOCUMENT_REMARKS as varchar), '') || '|' || coalesce(cast(RECEIVED_TIME as varchar), '') || '|' || coalesce(cast(ATTACHMENT_SEQUENCE_NUMBER as varchar), '') || '|' || coalesce(cast(RELATED_PRE_AUTHORISATION_REFERENCE as varchar), '') || '|' || coalesce(cast(ORIGINATING_FAX_NUMBER as varchar), '')))
                end as SAT_DOCUMENT_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_DOCUMENT_HK is not null
  and SAT_DOCUMENT_DEFINITION_HASHDIFF is not null
